div.script:


(function () {

    'use strict';


    document.addEventListener(
        'DOMContentLoaded',
        function () {

            document
                .querySelectorAll(
                    '.cc-services-page a[href^="#"]'
                )
                .forEach(
                    function (link) {

                        link.addEventListener(
                            'click',
                            function (event) {

                                var href =
                                    this.getAttribute(
                                        'href'
                                    );


                                if (
                                    !href ||
                                    href === '#'
                                ) {
                                    return;
                                }


                                var target = null;


                                try {

                                    target =
                                        document.querySelector(
                                            href
                                        );

                                } catch (error) {

                                    return;
                                }


                                if (!target) {
                                    return;
                                }


                                event.preventDefault();


                                target.scrollIntoView({
                                    behavior: 'smooth',
                                    block: 'start'
                                });

                            }
                        );

                    }
                );

        }
    );

})();
